"use client";

import { motion, useReducedMotion } from "framer-motion";

const MEDALLION = 64;
const HALF = MEDALLION / 2;

export function ErrorState({
  title,
  description,
  action,
}: {
  title: string;
  description: string;
  action?: { label: string; onClick?: () => void };
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="relative flex w-full flex-col items-center gap-4 overflow-hidden rounded-2xl border border-slate-200 bg-white px-8 py-10 text-center dark:border-slate-700 dark:bg-neutral-950">
      <motion.span
        aria-hidden
        className="absolute inset-x-0 top-0 h-0.5 bg-rose-500"
        initial={{ scaleX: 0 }}
        animate={{ scaleX: 1 }}
        transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
        style={{ transformOrigin: "center" }}
      />

      <div className="relative flex items-center justify-center" style={{ width: MEDALLION, height: MEDALLION }}>
        {/* halo: an ongoing urgency pulse, faster than the empty state's ambient breathing */}
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full blur-md bg-rose-400/30 dark:bg-rose-400/20"
          animate={shouldReduceMotion ? { opacity: 0.3 } : { opacity: [0.2, 0.42, 0.2] }}
          transition={shouldReduceMotion ? { duration: 0.2 } : { duration: 1.6, repeat: Infinity, ease: "easeInOut" }}
        />

        {/* one-shot alert ring, timed with the icon shake */}
        {!shouldReduceMotion && (
          <motion.span
            aria-hidden
            className="absolute rounded-full border-2 border-rose-400/60"
            style={{
              width: MEDALLION,
              height: MEDALLION,
              top: "50%",
              left: "50%",
              marginLeft: -HALF,
              marginTop: -HALF,
            }}
            initial={{ scale: 0.7, opacity: 0.9 }}
            animate={{ scale: 1.6, opacity: 0 }}
            transition={{ duration: 0.55, ease: [0.16, 1, 0.3, 1], delay: 0.05 }}
          />
        )}

        <div
          className="relative flex items-center justify-center rounded-full border border-rose-300 bg-rose-50 text-rose-500 dark:border-rose-500/40 dark:bg-rose-500/10 dark:text-rose-400"
          style={{ width: MEDALLION, height: MEDALLION }}
        >
          <motion.svg
            viewBox="0 0 24 24"
            width="30"
            height="30"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden
            initial={{ opacity: 0 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, x: [0, -4, 4, -3, 3, 0] }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
            <circle cx="12" cy="12" r="9" />
            <line x1="12" y1="8" x2="12" y2="13" />
            <line x1="12" y1="16" x2="12.01" y2="16" />
          </motion.svg>
        </div>
      </div>

      <div className="flex flex-col gap-1.5">
        <h3 className="text-base font-semibold text-slate-900 dark:text-white">{title}</h3>
        <p className="text-sm leading-relaxed text-slate-500 dark:text-slate-400">{description}</p>
      </div>

      {action && (
        <motion.button
          onClick={action.onClick}
          whileHover={shouldReduceMotion ? undefined : { y: -2 }}
          whileTap={{ scale: 0.96, y: 0 }}
          transition={{ type: "spring", stiffness: 500, damping: 30 }}
          className="group relative mt-1 inline-flex items-center justify-center overflow-hidden rounded-lg bg-rose-600 px-4 py-2 text-sm font-medium text-white shadow-[0_1px_2px_rgba(225,29,72,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-rose-500 hover:shadow-[0_10px_20px_-8px_rgba(225,29,72,0.6)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-rose-500"
        >
          <span
            aria-hidden
            className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
          />
          <span className="relative">{action.label}</span>
        </motion.button>
      )}
    </div>
  );
}
